\set ON_ERROR_STOP on
begin;set local statement_timeout='8s';
\ir grouped/fixture.sql
select pg_temp.group_checkout('pending','ach',array[5,10,15],true);
select pg_temp.check('all lines awaiting single root','PREPARE',(select count(*)=3 from public.money_board_group_items where group_id=pg_temp.group_id('pending')));
select boss_private.rails_dispatch(pg_temp.f('checkout-pending'));
select pg_temp.receive('pending','ach_pending');
select pg_sleep(1.05);
select pg_temp.check('expired clock still payment pending','PENDING',pg_temp.cart('recover',md5('pending')||md5('grouppending'))->>'state'='payment_pending');
select pg_temp.check('every expired line held','PENDING',(select bool_and(not boss_private.money_board_tile_available(tile_id))from public.money_board_group_items where group_id=pg_temp.group_id('pending')));
select pg_temp.conflict('pending cannot ordinary cancel',format('select pg_temp.cart(%L,%L)','cancel',md5('pending')||md5('grouppending')));
select pg_temp.conflict('pending cannot ordinary expire',format('select pg_temp.cart(%L,%L)','expire',md5('pending')||md5('grouppending')));
select pg_temp.conflict('pending board cannot archive',format('update public.money_boards set status=%L where id=%L','archived',pg_temp.fid('board')));
select pg_temp.check('ACH pending raises nothing','PROGRESS',public.boss_money_board_public(pg_temp.fpath('share'))->'progress'->>'verified_gross_minor'='0');
select pg_temp.check('pending amount exactly group principal','PROGRESS',public.boss_money_board_public(pg_temp.fpath('share'))->'progress'->>'pending_checkout_minor'='3000');
select pg_temp.receive('pending','unknown');
select pg_temp.check('unknown recovery does not request new dispatch','PENDING',pg_temp.cart('recover',md5('pending')||md5('grouppending'))->>'state'='payment_pending');
select boss_private.rails_dispatch(pg_temp.f('checkout-pending'));
select pg_temp.check('unknown uses original operation','IDEMPOTENCY',(select count(*)=1 from public.provider_operations where checkout_id=pg_temp.f('checkout-pending')));
select pg_temp.receive('pending','settled');
select pg_temp.check('late final ACH success confirms whole group','SUCCESS',pg_temp.cart('recover',md5('pending')||md5('grouppending'))->>'state'='confirmed');
select pg_temp.check('late committed success three permanent claims','SUCCESS',(select count(*)=3 and sum(amount_minor)=3000 from public.money_board_tile_claims where group_id=pg_temp.group_id('pending')));
select pg_temp.receive('pending','settled');
select pg_temp.check('success replay one source one gift','IDEMPOTENCY',(select count(*)=1 from public.fundraising_success_evidence where id=pg_temp.group_evidence('pending'))and(select count(*)=1 from public.fundraising_reward_qualifications where evidence_id=pg_temp.group_evidence('pending')));
select pg_temp.check('wallet uses root principal once','WALLET',(select sum(amount_minor)=1500 from public.boss_bucks_grants where intent_id=(select intent_id from public.payment_checkouts where id=pg_temp.f('checkout-pending'))));
select pg_temp.refund_group('pending',101);
select pg_temp.check('proportional refund every cent','CORRECTION',(select sum(amount_minor)=101 from public.money_board_tile_corrections where tile_id in(pg_temp.tile(5),pg_temp.tile(10),pg_temp.tile(15))));
select pg_temp.check('101 Hamilton 17 34 50','CORRECTION',(select array_agg(r.amount_minor order by t.ordinal)=array[17,34,50]::bigint[]from public.money_board_tile_corrections r join public.money_board_tiles t on t.id=r.tile_id));
select pg_temp.check('net progress correction once','PROGRESS',public.boss_money_board_public(pg_temp.fpath('share'))->'progress'->>'net_raised_minor'='2899');
select pg_temp.refund_group('pending',483,jsonb_build_array(jsonb_build_object('tile_id',pg_temp.tile(5),'amount_minor',483)));
select pg_temp.check('exact tile allocation used','CORRECTION',exists(select 1 from public.money_board_tile_corrections where tile_id=pg_temp.tile(5)and amount_minor=483 and algorithm='exact_v1'));
select pg_temp.refund_group('pending',2416);
select pg_temp.check('capped repeat corrections reconcile original source','CORRECTION',(select sum(amount_minor)=3000 from public.money_board_tile_corrections));
select pg_temp.check('zero net retains permanent tiles','PROGRESS',public.boss_money_board_public(pg_temp.fpath('share'))->'progress'->>'net_raised_minor'='0'and public.boss_money_board_public(pg_temp.fpath('share'))->'progress'->>'claimed_count'='3');
select pg_temp.check('refund does not reopen any paid tile','PERMANENCE',not boss_private.money_board_tile_available(pg_temp.tile(5))and not boss_private.money_board_tile_available(pg_temp.tile(10))and not boss_private.money_board_tile_available(pg_temp.tile(15)));
select pg_temp.check('refund preserves source correction lineage','WALLET',exists(select 1 from public.boss_bucks_source_corrections where remaining_source_minor=0 and entitlement_minor=0));
select pg_temp.group_checkout('failure','card',array[2,3]);select boss_private.rails_dispatch(pg_temp.f('checkout-failure'));select pg_temp.receive('failure','failed');
select pg_temp.check('definitive failure separate from unpaid','RECOVERY',boss_private.money_board_group_state(pg_temp.group_id('failure'))='failed');
select pg_temp.check('failed reload remains distinct after release','RECOVERY',pg_temp.cart('recover',md5('failure')||md5('groupfailure'))->>'state'='failed');
select pg_temp.check('failed holds safely released','RECOVERY',boss_private.money_board_tile_available(pg_temp.tile(2))and boss_private.money_board_tile_available(pg_temp.tile(3)));
select pg_temp.group_checkout('card','card',array[7,8]);select boss_private.rails_dispatch(pg_temp.f('checkout-card'));select pg_temp.receive('card','authorized');
select pg_temp.check('authorization is zero contribution','CARD',(select count(*)=0 from public.money_board_tile_claims where group_id=pg_temp.group_id('card')));
select pg_temp.receive('card','captured');
select pg_temp.check('verified capture claims all card tiles','CARD',(select count(*)=2 from public.money_board_tile_claims where group_id=pg_temp.group_id('card')));
select pg_temp.conflict('confirmed group cannot cancel',format('select pg_temp.cart(%L,%L)','cancel',md5('card')||md5('groupcard')));
set constraints all immediate;
select count(*)passed_assertions,'Grouped pending, card/ACH success, corrections, benefits' suite from pg_temp.phase5a_assertions;
rollback;
